import sqlite3,hashlib;c1=sqlite3.connect('data/tui_recomendador.db');c2=sqlite3.connect('data/tui_recomendador-javier.db');t1=c1.execute('SELECT COUNT(*) FROM resenas').fetchone()[0];t2=c2.execute('SELECT COUNT(*) FROM resenas').fetchone()[0];r1=c1.execute('SELECT texto_original FROM resenas WHERE texto_original IS NOT NULL').fetchall();r2=c2.execute('SELECT texto_original FROM resenas WHERE texto_original IS NOT NULL').fetchall();h1={hashlib.md5(t[0].strip().lower().encode()).hexdigest() for t in r1 if t[0] and len(t[0])>10};h2={hashlib.md5(t[0].strip().lower().encode()).hexdigest() for t in r2 if t[0] and len(t[0])>10};comunes=h1&h2;union=h1|h2;print(f'DB1 (tui_recomendador): {t1} registros, {len(h1)} unicos');print(f'DB2 (javier): {t2} registros, {len(h2)} unicos');print(f'En comun: {len(comunes)}');print(f'Solo en DB1: {len(h1-h2)}');print(f'Solo en DB2: {len(h2-h1)}');print(f'UNION total sin duplicados: {len(union)}');print(f'Cruce: {len(comunes)/min(len(h1),len(h2))*100:.1f}%');c1.close();c2.close()

